'use strict';
const $=s=>document.querySelector(s), roots=['#islandContent','#settingsContent'];
let s, pendingAction=null, returnFocus=null, epoch=0, toastTimer;
function reset(){epoch++;s={enabled:true,level:86,limit:80,draft:80,plugged:true,authorized:true,supported:true,known:true,sleep:false,mode:'auto',target:80,start:86,busy:false,error:null,recovery:false,failNext:false};$('#scenario').value='normal';render();}
function message(text){$('#demoStatus').textContent=text;$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2800);}
function label(){if(s.recovery)return '等待确认恢复';if(s.error)return '操作未完成';if(!s.known)return '读数暂不可用';if(!s.authorized)return '需要授权';if(s.sleep)return s.enabled?'睡眠中 · 遵守上限':'睡眠中';if(s.mode==='discharge')return '主动放电中';if(!s.plugged)return '电池供电';if(!s.enabled)return '系统管理充电';return s.level>=s.limit?'已暂停充电':'正在充电';}
function hint(){if(!s.known)return '暂不可用';if(s.mode==='discharge')return `目标 ${s.target}% · 上限仍为 ${s.limit}%`;if(s.enabled)return `充电上限 ${s.limit}%`;return '保护已关闭';}
function blocked(){return s.busy||s.recovery||!s.known||s.sleep;}
function panel(prefix){const off=blocked()||!s.authorized,disOff=off||!s.enabled||!s.plugged||!s.supported||s.level<=20;let reason=!s.enabled?'先开启电池保护':!s.plugged?'接上电源后可用':!s.supported?'当前设备暂不支持':s.sleep?'睡眠时不可操作':s.level<=20?'电量过低，暂不可用':'按指定目标降低电量';
return `<div class="battery-summary"><div class="reading"><div class="battery-icon" aria-hidden="true"><div class="battery-fill" style="width:${s.known?s.level:0}%"></div></div><div class="percent">${s.known?s.level:'—'}<small>${s.known?'%':''}</small></div></div><div class="summary-copy"><div class="state-label ${s.error||s.recovery||!s.known||!s.authorized?'warning':''}">${label()}</div><div class="source">${s.plugged?'已接通电源':'未接电源'}</div></div></div>
<div class="control-row protection-row"><div><div class="control-title">电池保护</div><div class="control-copy">${hint()}</div></div><button class="switch" data-act="toggle" role="switch" aria-label="电池保护" aria-checked="${s.enabled}" ${off?'disabled':''}></button></div>
<div class="limit-block"><div class="control-row"><label class="control-title" for="${prefix}-limit">充电上限</label><output class="limit-output" for="${prefix}-limit">${s.draft}%</output></div><input id="${prefix}-limit" class="range" type="range" min="80" max="100" step="1" value="${s.draft}" aria-label="充电上限" ${off||s.mode==='discharge'?'disabled':''}><div class="range-labels"><span>80%</span><span>100%</span></div><div class="apply-row" ${s.draft===s.limit?'hidden':''}><span>${s.enabled?'尚未应用':'仅保存，开启后生效'}</span><button class="primary" data-act="apply" ${off?'disabled':''}>${s.enabled?'应用':'保存'}</button></div></div>
<div class="control-row discharge-row"><div><div class="control-title">${s.mode==='discharge'?'正在放电至 '+s.target+'%':'主动放电'}</div><div class="control-copy">${s.mode==='discharge'?'停止后恢复上限管理':reason}</div></div><button class="discharge-button" data-act="discharge" ${s.mode==='discharge'?(s.busy?'disabled':''):(disOff?'disabled':'')}>${s.mode==='discharge'?'停止放电':'开始放电'}</button></div>
${s.mode==='discharge'?`<div class="progress" aria-hidden="true"><i style="width:${100*(s.start-s.level)/Math.max(1,s.start-s.target)}%"></i></div>`:''}
${s.busy?'<div class="busy-note" role="status">'+(s.recovery?'正在恢复系统管理…':'正在确认操作结果…')+'</div>':''}
${s.error?`<div class="notice" role="alert">${s.error}<button data-act="retry" ${s.busy?'disabled':''}>重试</button></div>`:''}
${!s.authorized?'<div class="notice">需要授权后才能管理充电。<button data-act="authorize">设置权限</button></div>':''}
${!s.known?'<div class="notice">暂时无法读取电池状态，未执行新的控制。<button data-act="refresh">重新读取</button></div>':''}`;}
function render(){roots.forEach((r,i)=>$(r).innerHTML=panel(i?'settings':'island'));$('#compactText').textContent=(s.known?s.level+'%':'—')+(s.enabled?' · 保护':'');$('#advance').disabled=s.busy||!s.known||s.sleep;}
function request(action){if(s.busy)return;s.error=null;s.busy=true;if(action.kind==='disable')s.recovery=true;render();const gen=++epoch;setTimeout(()=>{if(gen!==epoch)return;s.busy=false;if(s.failNext){s.failNext=false;s.error=action.kind==='disable'?'尚未确认解除限制，不能标记为已关闭。请重试恢复。':'操作未成功，原状态保持不变。请重试。';s.retry=action;render();message('模拟：操作失败，未把请求当成成功。');return;}s.error=null;s.recovery=false;switch(action.kind){case'enable':s.enabled=true;break;case'disable':s.enabled=false;s.mode='auto';break;case'limit':s.limit=action.value;s.draft=action.value;break;case'discharge':s.mode='discharge';s.target=action.value;s.start=s.level;break;case'stop':s.mode='auto';break;}render();message('模拟：'+({enable:'已开启保护',disable:'已恢复系统管理',limit:'上限已保存为 '+s.limit+'%',discharge:'开始放电至 '+s.target+'%',stop:'已停止放电，恢复上限管理'}[action.kind]));},550);}
function showAction(kind){pendingAction=kind;returnFocus=document.activeElement;$('#actionTitle').textContent=kind==='disable'?'关闭电池保护？':'主动放电';$('#actionText').textContent=kind==='disable'?'将解除 SuperIsland 的充电限制，恢复系统管理。'+(s.mode==='discharge'?'当前主动放电也会停止。':''):'接着电源，将电量降低到指定目标。你可以随时停止。';$('#targetRow').hidden=kind!=='discharge';$('#target').disabled=kind!=='discharge';$('#target').max=Math.max(20,s.level-1);$('#target').value=Math.max(20,Math.min(s.limit,s.level-1));$('#targetHelp').textContent=`当前 ${s.level}%，目标需低于当前电量，最低 20%。结束后恢复 ${s.limit}% 上限管理；若目标更低，可能重新充电。`;$('#confirmAction').textContent=kind==='disable'?'关闭并恢复':'开始放电';$('#dialogError').textContent='';$('#actionDialog').showModal();if(kind==='discharge')$('#target').focus();else $('#cancelAction').focus();}
roots.forEach(root=>{$(root).addEventListener('input',e=>{if(!e.target.matches('.range'))return;s.draft=Number(e.target.value);document.querySelectorAll('.range').forEach(x=>x.value=s.draft);document.querySelectorAll('.limit-output').forEach(x=>x.textContent=s.draft+'%');document.querySelectorAll('.apply-row').forEach(x=>x.hidden=s.draft===s.limit);});$(root).addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;switch(b.dataset.act){case'toggle':s.enabled?showAction('disable'):request({kind:'enable'});break;case'apply':request({kind:'limit',value:s.draft});break;case'discharge':s.mode==='discharge'?request({kind:'stop'}):showAction('discharge');break;case'retry':request(s.retry);break;case'authorize':s.authorized=true;render();message('模拟授权通过；真实版本需本人完成系统授权。');break;case'refresh':s.known=true;render();message('模拟：已重新读取电量。');break;}});});
$('#actionForm').addEventListener('submit',e=>{e.preventDefault();const value=Number($('#target').value);if(pendingAction==='discharge'&&(!Number.isInteger(value)||value<20||value>=s.level)){$('#dialogError').textContent='请输入 20% 至 '+(s.level-1)+'% 的整数。';return;}const kind=pendingAction;$('#actionDialog').close();request({kind,value});});
$('#cancelAction').onclick=()=>$('#actionDialog').close();$('#actionDialog').addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus();});
$('#settings').onclick=()=>$('#settingsDialog').showModal();$('#closeSettings').onclick=()=>$('#settingsDialog').close();$('#settingsDialog').addEventListener('close',()=>$('#settings').focus());
$('#collapse').onclick=()=>{$('#island').hidden=true;$('#compact').hidden=false;$('#compact').focus();};$('#compact').onclick=()=>{$('#compact').hidden=true;$('#island').hidden=false;$('#collapse').focus();};
$('#scenario').onchange=e=>{const choice=e.target.value;epoch++;s.busy=false;s.error=null;s.recovery=false;s.failNext=false;s.known=true;s.authorized=true;s.supported=true;s.plugged=true;s.sleep=false;
if(choice==='sleep'){s.sleep=true;s.mode='auto';message('模拟睡眠：保留上限，结束主动放电；醒来不续跑。此处理为本稿建议。');}else if(choice==='unplugged'){s.plugged=false;s.mode='auto';message('模拟拔电：主动放电结束，保护设置保留。');}else if(choice==='permission'){s.authorized=false;s.enabled=false;s.mode='auto';message('模拟未授权：不会显示保护已生效。');}else if(choice==='unsupported'){s.supported=false;s.mode='auto';message('模拟：仍可限充，主动放电不可用。');}else if(choice==='unknown'){s.known=false;s.mode='auto';message('模拟读数缺失，不把未知当作 0%。');}else if(choice==='failure'){s.failNext=true;message('请调上限、放电或关闭保护，下一次操作将模拟失败。');}else{s.level=choice==='charging'?72:86;s.mode='auto';message('模拟场景已切换。');}render();};
$('#advance').onclick=()=>{if(s.mode==='discharge'){s.level=Math.max(s.target,s.level-3);if(s.level===s.target){s.mode='auto';message('模拟：已达到目标，主动放电结束，恢复上限管理。');}else message('模拟：电量下降 3%。');}else if(s.plugged){const end=s.enabled?s.limit:100;s.level=s.level<end?Math.min(end,s.level+3):s.level;message(s.level>=end?'模拟：已到上限，不会主动降低电量。':'模拟：电量增加 3%。');}else{s.level=Math.max(0,s.level-3);message('模拟：电池供电，电量下降 3%。');}render();};
$('#reset').onclick=()=>{$('#actionDialog').close();$('#settingsDialog').close();reset();message('已重置演示，真实电池未受影响。');};reset();
